function s(r,a="YYYY-MM-DD HH:mm:ss"){if(!r)return"-";const e=typeof r=="string"?new Date(r):new Date(Number(r)*1e3);if(isNaN(e.getTime()))return"-";const t=n=>n.toString().padStart(2,"0");return a.replace("YYYY",e.getFullYear().toString()).replace("MM",t(e.getMonth()+1)).replace("DD",t(e.getDate())).replace("HH",t(e.getHours())).replace("mm",t(e.getMinutes())).replace("ss",t(e.getSeconds()))}export{s as f};
